g=[[8]*18 for _ in range(12)]
pts=[(2,6),(2,12),(3,13),(4,13),(5,6),(5,7),(5,8),(5,10),(5,11),(5,12),(7,6),(8,13),(10,6),(10,12),(10,13)]
for r,c in pts:g[r][c]=4
out=[row[:] for row in g]
# fill bounded horizontal/vertical gaps with at most 4 intervening cells
for r in range(12):
 cs=[c for c in range(18) if g[r][c]==4]
 for a,b in zip(cs,cs[1:]):
  if b-a-1<=4:
   for c in range(a+1,b):out[r][c]=2
for c in range(18):
 rs=[r for r in range(12) if g[r][c]==4]
 for a,b in zip(rs,rs[1:]):
  if b-a-1<=4:
   for r in range(a+1,b):out[r][c]=2
# demonstrated right-edge short tails, treating last column as boundary and recoloring interior
for r in range(12):
 cs=[c for c in range(18) if g[r][c]==4]
 if cs:
  a=cs[-1]; n=17-a-1
  if 0<n<=4:
   for c in range(a+1,17):out[r][c]=2
print(out)

